tests:
test({ sr: 'broji ponavljanja', en: 'counts repeated words' }, () => {
  expect(countWords('a b a')).toEqual({ a: 2, b: 1 });
});
test({ sr: 'ne razlikuje velika i mala slova', en: 'ignores letter case' }, () => {
  expect(countWords('Hello hello')).toEqual({ hello: 2 });
});
test({ sr: 'prazan tekst daje prazan objekat', en: 'empty text gives an empty object' }, () => {
  expect(countWords('')).toEqual({});
});

hiddenTests:
test('multiple spaces between words', () => {
  expect(countWords('a   b  a')).toEqual({ a: 2, b: 1 });
});
test('leading and trailing spaces', () => {
  expect(countWords('  a b  ')).toEqual({ a: 1, b: 1 });
});

solutions.code:
function countWords(text) {
  const counts = {};
  for (const word of text.toLowerCase().split(/\s+/)) {
    if (!word) continue;
    counts[word] = (counts[word] ?? 0) + 1;
  }
  return counts;
}
